def hidden_rule_fn(state):
    grid = [row[:] for row in state]
    rows = len(grid)
    cols = len(grid[0])
    next_grid = [[0]*cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            coord_class = (r + c) % 3

            # Get neighbors based on coord_class
            neighbors = []

            if coord_class == 0:
                # Diagonal tetrad: NE, NW, SE, SW
                for dr, dc in [(-1, 1), (-1, -1), (1, 1), (1, -1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        neighbors.append(grid[nr][nc])
            elif coord_class == 1:
                # von Neumann quad: N, S, E, W
                for dr, dc in [(-1, 0), (1, 0), (0, 1), (0, -1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        neighbors.append(grid[nr][nc])
            elif coord_class == 2:
                # axial-2 quad: cells at distance 2 along N,S,E,W
                for dr, dc in [(-2, 0), (2, 0), (0, 2), (0, -2)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        neighbors.append(grid[nr][nc])

            # Count f0, f1, f2
            f0 = neighbors.count(0)
            f1 = neighbors.count(1)
            f2 = neighbors.count(2)

            # Determine next state based on counts
            # Need to figure out the rule from training data

            # Let's try: next state = majority of neighbors, with some tie-breaking
            # Or maybe it's based on specific count patterns

            # For now, let's try a simple approach: 
            # If f1 > f0 and f1 > f2: next = 1
            # If f2 > f0 and f2 > f1: next = 2
            # If f0 > f1 and f0 > f2: next = 0
            # Ties: prefer 0

            if f1 > f0 and f1 > f2:
                next_grid[r][c] = 1
            elif f2 > f0 and f2 > f1:
                next_grid[r][c] = 2
            else:
                next_grid[r][c] = 0

    return next_grid

def hidden_rule_fn(state):
    grid = {}
    for p in state:
        grid[(p['x'], p['y'])] = p

    particles = list(state)
    zex_particles = [p for p in particles if p['type'] == 'ZEX']
    glorp_particles = [p for p in particles if p['type'] == 'GLORP']

    def toroidal_delta(a, b):
        dx = (b - a) % 8
        if dx > 4:
            dx = dx - 8
        return dx

    def chromodistance(p, q):
        dx = abs((q['x'] - p['x']) % 8)
        dy = abs((q['y'] - p['y']) % 8)
        if dx > 4:
            dx = 8 - dx
        if dy > 4:
            dy = 8 - dy
        dist = max(dx, dy)
        if p['type'] != q['type']:
            dist += 1
        return dist

    def nearest_partner(p, partners):
        best_dist = float('inf')
        best_partner = None
        for partner in partners:
            d = chromodistance(p, partner)
            if d < best_dist or (d == best_dist and (partner['x'], partner['y']) < (best_partner['x'], best_partner['y'])):
                best_dist = d
                best_partner = partner
        return best_partner

    def move_toward(p, target):
        dx = toroidal_delta(p['x'], target['x'])
        dy = toroidal_delta(p['y'], target['y'])
        new_x = p['x']
        new_y = p['y']
        if abs(dx) >= abs(dy):
            if dx != 0:
                new_x = (p['x'] + (1 if dx > 0 else -1)) % 8
        else:
            if dy != 0:
                new_y = (p['y'] + (1 if dy > 0 else -1)) % 8
        return new_x, new_y

    def move_away(p, target):
        dx = toroidal_delta(p['x'], target['x'])
        dy = toroidal_delta(p['y'], target['y'])
        new_x = p['x']
        new_y = p['y']
        # Move away along axis with larger signed toroidal delta magnitude
        # x-axis preferred on tie
        if abs(dx) >= abs(dy):
            if dx != 0:
                new_x = (p['x'] - (1 if dx > 0 else -1)) % 8
        else:
            if dy != 0:
                new_y = (p['y'] - (1 if dy > 0 else -1)) % 8
        return new_x, new_y

    next_particles = []

    for p in particles:
        if p['type'] == 'ZEX':
            other_zex = [q for q in zex_particles if q is not p]
            if other_zex:
                target = nearest_partner(p, other_zex)
                nx, ny = move_toward(p, target)
            else:
                nx, ny = p['x'], p['y']
        else:  # GLORP
            other_zex = zex_particles
            if other_zex:
                target = nearest_partner(p, other_zex)
                nx, ny = move_away(p, target)
            else:
                nx, ny = p['x'], p['y']

        next_particles.append({'type': p['type'], 'x': nx, 'y': ny})

    return next_particles

def hidden_rule_fn(state):
    # For each particle, find its nearest neighbor (by grolp_dist)
    # Move each particle one step toward its nearest neighbor

    def wrap_dx(a, b):
        d = b - a
        if d > 4:
            d -= 8
        elif d < -4:
            d += 8
        return d

    def wrap_dy(a, b):
        d = b - a
        if d > 4:
            d -= 8
        elif d < -4:
            d += 8
        return d

    def grolp_dist(p, q):
        if p["type"] != q["type"]:
            return abs(wrap_dx(p["x"], q["x"])) + 2 * abs(wrap_dy(p["y"], q["y"]))
        else:
            return abs(wrap_dx(p["x"], q["x"])) * abs(wrap_dy(p["y"], q["y"])) + 1

    def step_toward(p, target):
        # Compute the direction from p to target
        dx = wrap_dx(p["x"], target["x"])
        dy = wrap_dy(p["y"], target["y"])

        if p["type"] != target["type"]:
            # Different types: prioritize y direction (weight 2)
            if abs(dy) >= abs(dx):
                # Move in y direction
                if dy > 0:
                    return {"type": p["type"], "x": p["x"], "y": (p["y"] + 1) % 8}
                elif dy < 0:
                    return {"type": p["type"], "x": p["x"], "y": (p["y"] - 1) % 8}
                else:
                    # dy == 0, move in x
                    if dx > 0:
                        return {"type": p["type"], "x": (p["x"] + 1) % 8, "y": p["y"]}
                    elif dx < 0:
                        return {"type": p["type"], "x": (p["x"] - 1) % 8, "y": p["y"]}
                    else:
                        return p
            else:
                # Move in x direction
                if dx > 0:
                    return {"type": p["type"], "x": (p["x"] + 1) % 8, "y": p["y"]}
                elif dx < 0:
                    return {"type": p["type"], "x": (p["x"] - 1) % 8, "y": p["y"]}
                else:
                    if dy > 0:
                        return {"type": p["type"], "x": p["x"], "y": (p["y"] + 1) % 8}
                    elif dy < 0:
                        return {"type": p["type"], "x": p["x"], "y": (p["y"] - 1) % 8}
                    else:
                        return p
        else:
            # Same type: distance is |dx|*|dy| + 1
            # We want to minimize this. Moving in either direction changes dx or dy.
            # If dx == 0 or dy == 0, distance = 1 regardless (can't reduce further in that dim)
            # Try moving in x first, then y
            if dx != 0 or dy != 0:
                # Check if moving in x reduces distance
                new_dx = abs(wrap_dx(p["x"] + (1 if dx > 0 else -1, 0), target["x"]))
                new_dy = abs(dy)
                new_dist_x = new_dx * new_dy + 1

                new_dx2 = abs(dx)
                new_dy2 = abs(wrap_dy(p["y"] + (1 if dy > 0 else -1, 0), target["y"]))
                new_dist_y = new_dx2 * new_dy2 + 1

                if new_dist_x < new_dist_y:
                    if dx > 0:
                        return {"type": p["type"], "x": (p["x"] + 1) % 8, "y": p["y"]}
                    else:
                        return {"type": p["type"], "x": (p["x"] - 1) % 8, "y": p["y"]}
                elif new_dist_y < new_dist_x:
                    if dy > 0:
                        return {"type": p["type"], "x": p["x"], "y": (p["y"] + 1) % 8}
                    else:
                        return {"type": p["type"], "x": p["x"], "y": (p["y"] - 1) % 8}
                else:
                    # Tie - try x first
                    if dx != 0:
                        if dx > 0:
                            return {"type": p["type"], "x": (p["x"] + 1) % 8, "y": p["y"]}
                        else:
                            return {"type": p["type"], "x": (p["x"] - 1) % 8, "y": p["y"]}
                    else:
                        if dy > 0:
                            return {"type": p["type"], "x": p["x"], "y": (p["y"] + 1) % 8}
                        else:
                            return {"type": p["type"], "x": p["x"], "y": (p["y"] - 1) % 8}
            return p

    # Build next state: each particle moves toward its nearest neighbor
    next_state = []
    for i, p in enumerate(state):
        # Find nearest neighbor (excluding self)
        min_dist = float('inf')
        nearest = None
        for j, q in enumerate(state):
            if i == j:
                continue
            d = grolp_dist(p, q)
            if d < min_dist:
                min_dist = d
                nearest = q
            elif d == min_dist:
                # Tie-breaking: pick the one that comes first in some order
                # Let's try: prefer smaller index
                if j < state.index(nearest):
                    nearest = q

        if nearest:
            next_state.append(step_toward(p, nearest))
        else:
            next_state.append(p)

    return next_state
